      h += `<div class="row-btns"><button type="button" class="btn primary" data-mig="add"${m || c.N >= 6 ? ' disabled' : ''}>+ Добавить шард</button>${c.N >= 6 ? '<span class="lt-sub">максимум 6 шардов</span>' : ''}</div>`;
